{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Disopyramide, which shares the phenyl-pyridyl core and a basic tertiary amine with the query, has an absolute oral bioavailability of 81.76 ± 17.90% in healthy volunteers, directly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Dextromoramide, a diphenyl-substituted basic amide analogue, is reported to have good oral bioavailability in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Fexofenadine, despite being a zwitterionic P-gp substrate, has an absolute oral bioavailability of 30% in human volunteers, above the 20% threshold; the query lacks the carboxylic acid and is expected to be at least as absorbable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Doxylamine, containing the same phenyl-pyridyl motif and a basic dimethylamine, has about 50% oral bioavailability in normal subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Bepotastine, a pyridyl-phenyl piperidine analogue, has >80% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Desethyloxybutynin enantiomers have 62–78% oral bioavailability in healthy adults, supporting high F for a tertiary-alcohol basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Nicotine oral bioavailability is reported as 20–45% in humans, at or above the threshold, providing weak supportive evidence.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Imidafenacin, a diphenyl amide with a basic heterocycle, has an absolute oral bioavailability of 57.8% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Ebastine, a diphenylmethoxy piperidine, has about 40% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "PEMA, a small phenyl amide, has at least 80% oral bioavailability in normal subjects, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence points to oral bioavailability at or above 20%, with the closest analogue disopyramide showing ~80–90% absolute F in humans. The query's high basic pKa and full ionization at physiological pH are potential permeability liabilities, but they are not sufficient to overturn the consistent supportive human data from multiple structurally related molecules.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself.",
    "Unknown efflux transporter interactions and first-pass metabolism for the query.",
    "The strongly basic 2,6-dimethylpiperidine may reduce passive permeability, but no direct permeability or absorption measurement is available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

